src = r'''
#include <torch/extension.h>
#include <cuda_fp16.h>
#include <cuda_runtime.h>
#include <limits>

template <typename scalar_t>
__global__ void maxpool1d_fp16_kernel(
    const scalar_t* __restrict__ input,
    scalar_t* __restrict__ output,
    const int batch,
    const int channels,
    const int seq_len,
    const int out_len,
    const int kernel_size,
    const int stride,
    const int padding,
    const int dilation) {

    const int idx = blockIdx.x * blockDim.x + threadIdx.x;
    const int total = batch * channels * out_len;
    if (idx >= total) return;

    // decode indices
    const int tmp = idx / out_len;
    const int out_i = idx % out_len;
    const int c = tmp % channels;
    const int b = tmp / channels;

    const int start = out_i * stride - padding;
    const int end   = start + (kernel_size - 1) * dilation;

    // half min value (acts as -inf)
    const scalar_t neg_inf = __float2half(-65504.0f);

    scalar_t max_val = neg_inf;

    #pragma unroll
    for (int k = 0; k < kernel_size; ++k) {
        const int in_idx = start + k * dilation;
        if (in_idx >= 0 && in_idx < seq_len) {
            const scalar_t val = input[(b * channels + c) * seq_len + in_idx];
            max_val = __hgt(val, max_val) ? val : max_val;
        }
    }

    output[(b * channels + c) * out_len + out_i] = max_val;
}

// Wrapper called from Python
void maxpool1d_forward(
    torch::Tensor input,
    torch::Tensor output,
    int kernel_size,
    int stride,
    int padding,
    int dilation) {

    const int batch   = input.size(0);
    const int channels= input.size(1);
    const int seq_len = input.size(2);
    const int out_len = output.size(2);

    const int threads = 256;
    const int total = batch * channels * out_len;
    const int blocks = (total + threads - 1) / threads;

    AT_DISPATCH_HALF_TYPES(input.scalar_type(), "maxpool1d_forward", ([&] {
        maxpool1d_fp16_kernel<scalar_t><<<blocks, threads, 0,
            at::cuda::getCurrentCUDAStream()>>>(
                input.data_ptr<scalar_t>(),
                output.data_ptr<scalar_t>(),
                batch,
                channels,
                seq_len,
                out_len,
                kernel_size,
                stride,
                padding,
                dilation);
    }));

    cudaError_t err = cudaGetLastError();
    if (err != cudaSuccess)
        AT_ERROR("CUDA error in maxpool1d_forward: ", cudaGetErrorString(err));
}

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("maxpool1d_forward", &maxpool1d_forward, "MaxPool1d forward (FP16)");
}
'''

# Compile the extension
maxpool_cuda = load_inline(name='maxpool_cuda',
                           cpp_sources='',
                           cuda_sources=src,
                           functions=['maxpool1d_forward'],
                           verbose=False)

# ----------------------------------------------------------------------
# Python model using the custom kernel
# ----------------------------------------------------------------------
class ModelNew(nn.Module):
    """
    Drop‑in replacement for the reference MaxPool1d using a custom CUDA kernel.
    All tensors are FP16.
    """
    def __init__(self,
                 kernel_size: int,
                 stride: int = None,
                 padding: int = 0,
                 dilation: int = 1,
                 return_indices: bool = False):
        super().__init__()
        self.kernel_size = kernel_size
        self.stride = stride if stride is not None else kernel_size
        self.padding = padding
        self.dilation = dilation
        if return_indices:
            raise NotImplementedError("return_indices=True is not supported in the custom kernel.")

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        if not x.is_cuda:
            raise RuntimeError("ModelNew only supports CUDA tensors.")
        if x.dtype != torch.float16:
            raise RuntimeError("ModelNew only supports torch.float16 tensors.")
        batch, channels, seq_len = x.shape
        k = self.kernel_size
        s = self.stride
        p = self.padding
        d = self.dilation

        # Output length follows PyTorch's formula
        out_len = math.floor((seq_len + 2 * p - d * (k - 1) - 1) / s + 1)

        out = torch.empty((batch, channels, out_len),
                          device=x.device,
                          dtype=torch.float16)

        maxpool_cuda.maxpool1d_forward(x,
                                       out,
                                       k,
                                       s,
                                       p,
                                       d)
        return out

# ----------------------------------------------------------------------
# Example usage matching reference script
# ----------------------------------------------------------------------
if __name__ == "__main__":
    batch_size = 64
    features = 192
    sequence_length = 65536

    kernel_size = 8
    stride = 1
    padding = 4
    dilation = 3
    return_indices = False

    model = ModelNew(kernel_size, stride, padding, dilation, return_indices).cuda().half()

    x = torch.rand(batch_size, features, sequence_length, device='cuda', dtype=torch.float16)
    y = model(x)
    print(y.shape)
